INSERT INTO courts(court_id,name,level,region) VALUES ('ct_local','Harbor City Housing Tribunal','仲裁委员会','Harbor City');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_adu','Harbor City Accessory Dwelling Unit Code 2026','ADU Code','Harbor City Planning Department','2026-07-01','现行有效','Detached garage conversion to rentable ADU requires zoning eligibility, building permit, egress, alarms, light and ventilation, utility plan, parking/access statement, and final inspection before tenant advertising.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_adu_core','stat_adu','Section 2.1',1,'Detached Garage ADU Eligibility','Detached garage conversion to ADU rental requires building permit, dwelling-use plan, independent entrance, emergency egress, minimum daylight and ventilation, smoke and carbon monoxide alarms, utility connection plan, and parking/access statement.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_egress','stat_adu','Section 3.4',2,'Emergency Egress','Sleeping area must have a compliant emergency escape and rescue opening with documented clear opening dimensions; noncompliant windows must be corrected before rental occupancy.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_alarm','stat_adu','Section 4.2',3,'Smoke and Carbon Monoxide Alarm','ADU rental unit must include smoke and carbon monoxide alarms in approved locations before occupancy or tenant advertising.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_lightvent','stat_adu','Section 5.2',4,'Light and Ventilation','Habitable room requires minimum light and ventilation or approved mechanical ventilation; bathroom exhaust must discharge independently.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_false_desc','stat_adu','Section 8.1',5,'Use Description','A dwelling conversion may not be described as storage, studio, office, workshop, or hobby room to avoid residential permit review.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_listing','stat_adu','Section 9.3',6,'Rental Advertising','A unit may be advertised as lawful rentable ADU only after zoning eligibility, permit status, required safety features, and inspection status are documented.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_residential_2020_01','Residential Building Code No. 23-20 (Consolidated)','RBC-20','Harbor City Building Division','2020-02-02','现行有效','Sets minimum standards for accessory structures. Local amendments take precedence over the model code.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2020_01_1','stat_residential_2020_01','Section 9.3',1,'Foundation and Slab','Slab-on-grade conversions must document existing slab thickness and vapor barrier; a structural observation report is required where the slab predates 1990. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2020_01_2','stat_residential_2020_01','Section 10.3',2,'Wall Framing','Converted framing must meet current lateral bracing requirements; existing garage door headers may be retained only with an engineer letter.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2020_01_3','stat_residential_2020_01','Section 2.2',3,'Roof and Attic Access','Habitable conversions require documented attic access and insulation baffles at eave vents. See the departmental checklist for submittal format.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2020_01_4','stat_residential_2020_01','Section 8.7',4,'Stairs and Landings','Any level change greater than 190 mm requires a compliant step and landing at exterior doors. Field verification occurs at the corresponding inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2020_01_5','stat_residential_2020_01','Section 12.5',5,'Weather Protection','Exterior wall assemblies must include a water-resistive barrier continuous with the existing structure. Alternative means may be approved by the building official.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_electrical_2021_02','Electrical Safety Ordinance No. 83-21 (Reissued) — Historic District Part','ESO-21','Harbor City Electrical Board','2021-11-24','现行有效','Applies to detached accessory structures in MU-1 districts. Local amendments take precedence over the model code.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_electrical_2021_02_1','stat_electrical_2021_02','Section 5.4',1,'Branch Circuits','A converted dwelling unit requires dedicated small-appliance branch circuits separate from the main residence panel. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_electrical_2021_02_2','stat_electrical_2021_02','Section 11.1',2,'GFCI and AFCI','GFCI protection is required at kitchenette, bathroom and exterior outlets; AFCI protection is required at sleeping areas. See the departmental checklist for submittal format.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_electrical_2021_02_3','stat_electrical_2021_02','Section 1.4',3,'Sub-panel Feed','Detached structures require a properly sized feeder, grounding electrode and disconnecting means. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_electrical_2021_02_4','stat_electrical_2021_02','Section 10.6',4,'Working Clearance','Panels must retain 900 mm clear working depth; storage may not encroach on that clearance. Field verification occurs at the corresponding inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_electrical_2021_02_5','stat_electrical_2021_02','Section 9.9',5,'Exterior Lighting','An independent entrance requires illumination controlled from inside the unit. Documentation must be retained for the life of the structure.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_plumbing_2023_03','Plumbing and Drainage Rules No. 66-23 for Marsh End','PDR-23','Harbor City Utilities Department','2023-02-20','现行有效','Adopted after the 2023 code cycle; enforced at plan check and field inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_plumbing_2023_03_1','stat_plumbing_2023_03','Section 6.3',1,'Sewer Connection','A new dwelling unit connection requires a capacity confirmation letter from the utility before rough plumbing inspection. See the departmental checklist for submittal format.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_plumbing_2023_03_2','stat_plumbing_2023_03','Section 6.2',2,'Water Metering','Sub-metering is optional for accessory units but the shutoff must be accessible without entering the main residence. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_plumbing_2023_03_3','stat_plumbing_2023_03','Section 12.7',3,'Fixture Seals and Venting','Every fixture requires an individual water seal and a vent connected to the existing stack or a new roof vent. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_plumbing_2023_03_4','stat_plumbing_2023_03','Section 8.2',4,'Backflow Prevention','Irrigation and hose bibs serving the rear yard require backflow devices. Field verification occurs at the corresponding inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_plumbing_2023_03_5','stat_plumbing_2023_03','Section 7.7',5,'Hot Water','Storage water heaters in habitable conversions require seismic strapping and a drain pan piped to daylight.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_zoning_2026_04','Zoning and Setback Bulletin No. 65-26 (Consolidated): Conversions','ZSB-26','Harbor City Planning Department','2026-05-09','现行有效','Adopted after the 2026 code cycle; enforced at plan check and field inspection. Amendments are published quarterly.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2026_04_1','stat_zoning_2026_04','Section 4.9',1,'Rear Yard Coverage','Accessory structures may occupy up to 50 percent of the required rear yard; existing nonconforming coverage may be retained if not expanded.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2026_04_2','stat_zoning_2026_04','Section 4.2',2,'Side Setback','A detached accessory structure must maintain a 1.2 m side setback unless the existing wall is fire-rated.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2026_04_3','stat_zoning_2026_04','Section 11.8',3,'Height Limit','Single-storey accessory structures are limited to 5 m measured to the roof midpoint.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2026_04_4','stat_zoning_2026_04','Section 9.5',4,'Lot Coverage','Total impervious coverage may not exceed the district maximum after conversion.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2026_04_5','stat_zoning_2026_04','Section 12.8',5,'Tree Protection','Work within the dripline of a protected tree requires an arborist report before permit issuance.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_neighborhood_2021_05','Neighborhood Notice Procedure No. 10-21 (Reissued)','NNP-21','Harbor City Clerk Office','2021-07-26','已废止','Consolidated 2021 revision superseding earlier departmental memoranda. Local amendments take precedence over the model code.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2021_05_1','stat_neighborhood_2021_05','Section 6.9',1,'Notice Radius','Applications for detached accessory dwelling conversions require mailed notice to owners within 100 m. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2021_05_2','stat_neighborhood_2021_05','Section 11.8',2,'Objection Window','Written objections must be filed within 14 days of notice; late objections are recorded but do not stay the permit. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2021_05_3','stat_neighborhood_2021_05','Section 11.2',3,'Hearing Threshold','A hearing is scheduled only where objections raise a code-based issue rather than general opposition. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2021_05_4','stat_neighborhood_2021_05','Section 7.7',4,'Response Record','The applicant response to each objection is entered into the permit case record. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2021_05_5','stat_neighborhood_2021_05','Section 10.3',5,'Appeal Rights','A permit decision may be appealed within 10 days by any party who filed a timely objection. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_fire_2023_06','Fire Prevention Standard No. 81-23 (Reissued)','FPS-23','Harbor City Fire Marshal','2023-06-11','现行有效','Sets minimum standards for additions.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2023_06_1','stat_fire_2023_06','Section 7.8',1,'Separation','A dwelling conversion sharing a wall with a garage requires a one-hour rated separation with self-closing doors. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2023_06_2','stat_fire_2023_06','Section 10.9',2,'Address Marking','Rear units must display an address marker visible from the access path. See the departmental checklist for submittal format.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2023_06_3','stat_fire_2023_06','Section 3.7',3,'Extinguisher','A portable extinguisher is recommended but not required for single accessory units. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2023_06_4','stat_fire_2023_06','Section 4.8',4,'Access Path','An unobstructed 900 mm path must connect the street to the unit entrance.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2023_06_5','stat_fire_2023_06','Section 7.3',5,'Alarm Interconnection','Where more than one alarm is installed, alarms must be interconnected so that activation of one sounds all. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_rental_2023_07','Rental Housing Registration No. 2-23 (Consolidated) — Rental Housing Part','RHR-23','Harbor City Housing Office','2023-09-09','现行有效','Sets minimum standards for rental registration. Local amendments take precedence over the model code.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2023_07_1','stat_rental_2023_07','Section 8.5',1,'Registration Duty','A newly created rental unit must be registered within 30 days of first occupancy. Field verification occurs at the corresponding inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2023_07_2','stat_rental_2023_07','Section 2.7',2,'Habitability Standard','Registered units must maintain heat, hot water, weatherproofing and functioning alarms. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2023_07_3','stat_rental_2023_07','Section 8.8',3,'Inspection Cycle','Registered rental units are subject to a cyclical inspection every four years.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2023_07_4','stat_rental_2023_07','Section 8.2',4,'Tenant Disclosure','The owner must disclose the permit status of an accessory unit to prospective tenants. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2023_07_5','stat_rental_2023_07','Section 12.6',5,'Fee Schedule','Registration fees are assessed annually and are not prorated. Documentation must be retained for the life of the structure.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_stormwater_2020_08','Stormwater and Grading No. 14-20 (Reissued) — Infill Sites Part','SG-20','Harbor City Public Works','2020-04-09','已修订','Applies to detached accessory structures in R-3 districts. Local amendments take precedence over the model code.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_stormwater_2020_08_1','stat_stormwater_2020_08','Section 1.4',1,'Drainage Away','Finished grade must fall away from the converted structure for the first 1.5 m. Field verification occurs at the corresponding inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_stormwater_2020_08_2','stat_stormwater_2020_08','Section 3.4',2,'Downspout Discharge','Downspouts may not discharge onto an adjacent property. See the departmental checklist for submittal format.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_stormwater_2020_08_3','stat_stormwater_2020_08','Section 7.6',3,'Permeable Area','Replacement of a driveway apron requires maintaining the district permeable minimum. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_stormwater_2020_08_4','stat_stormwater_2020_08','Section 10.6',4,'Erosion Control','Sites disturbing more than 50 sq m require erosion control during construction.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_stormwater_2020_08_5','stat_stormwater_2020_08','Section 12.4',5,'Grading Permit','A separate grading permit is required where cut or fill exceeds 0.6 m.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_residential_2022_09','Residential Building Code No. 48-22: Additions','RBC-22','Harbor City Building Division','2022-07-06','现行有效','Applies to detached accessory structures in MU-1 districts. Applies only to permits filed after the effective date.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2022_09_1','stat_residential_2022_09','Section 2.8',1,'Foundation and Slab','Slab-on-grade conversions must document existing slab thickness and vapor barrier; a structural observation report is required where the slab predates 1990.');
