INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2022_09_4','stat_residential_2022_09','Section 12.3',4,'Stairs and Landings','Any level change greater than 190 mm requires a compliant step and landing at exterior doors.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2022_09_5','stat_residential_2022_09','Section 1.7',5,'Weather Protection','Exterior wall assemblies must include a water-resistive barrier continuous with the existing structure. Field verification occurs at the corresponding inspection.');
