INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_electrical_2020_10_5','stat_electrical_2020_10','Section 9.8',5,'Exterior Lighting','An independent entrance requires illumination controlled from inside the unit.');
