INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_plumbing_2021_11_2','stat_plumbing_2021_11','Section 10.7',2,'Water Metering','Sub-metering is optional for accessory units but the shutoff must be accessible without entering the main residence.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_plumbing_2021_11_3','stat_plumbing_2021_11','Section 12.6',3,'Fixture Seals and Venting','Every fixture requires an individual water seal and a vent connected to the existing stack or a new roof vent. Noncompliance is corrected by written notice before final approval.');
