INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_plumbing_2021_11_5','stat_plumbing_2021_11','Section 12.6',5,'Hot Water','Storage water heaters in habitable conversions require seismic strapping and a drain pan piped to daylight. See the departmental checklist for submittal format.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_zoning_2022_12','Zoning and Setback Bulletin No. 15-22 (Supplement)','ZSB-22','Harbor City Planning Department','2022-02-17','现行有效','Sets minimum standards for additions. Local amendments take precedence over the model code.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2022_12_1','stat_zoning_2022_12','Section 8.7',1,'Rear Yard Coverage','Accessory structures may occupy up to 50 percent of the required rear yard; existing nonconforming coverage may be retained if not expanded. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2022_12_2','stat_zoning_2022_12','Section 7.4',2,'Side Setback','A detached accessory structure must maintain a 1.2 m side setback unless the existing wall is fire-rated. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2022_12_3','stat_zoning_2022_12','Section 1.1',3,'Height Limit','Single-storey accessory structures are limited to 5 m measured to the roof midpoint. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2022_12_4','stat_zoning_2022_12','Section 2.3',4,'Lot Coverage','Total impervious coverage may not exceed the district maximum after conversion. Field verification occurs at the corresponding inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2022_12_5','stat_zoning_2022_12','Section 8.2',5,'Tree Protection','Work within the dripline of a protected tree requires an arborist report before permit issuance. Documentation must be retained for the life of the structure.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_neighborhood_2024_13','Neighborhood Notice Procedure No. 39-24 (Amended) — Rental Housing Part','NNP-24','Harbor City Clerk Office','2024-06-17','现行有效','Interpretation guidance issued by Harbor City Clerk Office. Does not apply to structures under 10 sq m.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2024_13_1','stat_neighborhood_2024_13','Section 5.2',1,'Notice Radius','Applications for detached accessory dwelling conversions require mailed notice to owners within 100 m. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2024_13_2','stat_neighborhood_2024_13','Section 12.4',2,'Objection Window','Written objections must be filed within 14 days of notice; late objections are recorded but do not stay the permit. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2024_13_3','stat_neighborhood_2024_13','Section 4.7',3,'Hearing Threshold','A hearing is scheduled only where objections raise a code-based issue rather than general opposition.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2024_13_4','stat_neighborhood_2024_13','Section 1.8',4,'Response Record','The applicant response to each objection is entered into the permit case record.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2024_13_5','stat_neighborhood_2024_13','Section 5.4',5,'Appeal Rights','A permit decision may be appealed within 10 days by any party who filed a timely objection.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_fire_2019_14','Fire Prevention Standard No. 62-19 (Consolidated)','FPS-19','Harbor City Fire Marshal','2019-08-05','现行有效','Consolidated 2019 revision superseding earlier departmental memoranda. Does not apply to structures under 10 sq m.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2019_14_1','stat_fire_2019_14','Section 11.9',1,'Separation','A dwelling conversion sharing a wall with a garage requires a one-hour rated separation with self-closing doors. Field verification occurs at the corresponding inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2019_14_2','stat_fire_2019_14','Section 8.8',2,'Address Marking','Rear units must display an address marker visible from the access path. Field verification occurs at the corresponding inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2019_14_3','stat_fire_2019_14','Section 3.7',3,'Extinguisher','A portable extinguisher is recommended but not required for single accessory units. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2019_14_4','stat_fire_2019_14','Section 3.5',4,'Access Path','An unobstructed 900 mm path must connect the street to the unit entrance. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2019_14_5','stat_fire_2019_14','Section 11.5',5,'Alarm Interconnection','Where more than one alarm is installed, alarms must be interconnected so that activation of one sounds all.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_rental_2019_15','Rental Housing Registration No. 41-19 (Consolidated) for the Harbor Basin','RHR-19','Harbor City Housing Office','2019-05-19','现行有效','Applies to detached accessory structures in R-3 districts.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2019_15_1','stat_rental_2019_15','Section 3.8',1,'Registration Duty','A newly created rental unit must be registered within 30 days of first occupancy.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2019_15_2','stat_rental_2019_15','Section 5.9',2,'Habitability Standard','Registered units must maintain heat, hot water, weatherproofing and functioning alarms.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2019_15_3','stat_rental_2019_15','Section 10.2',3,'Inspection Cycle','Registered rental units are subject to a cyclical inspection every four years. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2019_15_4','stat_rental_2019_15','Section 3.7',4,'Tenant Disclosure','The owner must disclose the permit status of an accessory unit to prospective tenants. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2019_15_5','stat_rental_2019_15','Section 2.1',5,'Fee Schedule','Registration fees are assessed annually and are not prorated. See the departmental checklist for submittal format.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_stormwater_2020_16','Stormwater and Grading No. 69-20','SG-20','Harbor City Public Works','2020-03-14','已修订','Applies to detached accessory structures in R-2 districts. Applies only to permits filed after the effective date.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_stormwater_2020_16_1','stat_stormwater_2020_16','Section 7.4',1,'Drainage Away','Finished grade must fall away from the converted structure for the first 1.5 m.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_stormwater_2020_16_2','stat_stormwater_2020_16','Section 5.1',2,'Downspout Discharge','Downspouts may not discharge onto an adjacent property. Field verification occurs at the corresponding inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_stormwater_2020_16_3','stat_stormwater_2020_16','Section 11.1',3,'Permeable Area','Replacement of a driveway apron requires maintaining the district permeable minimum.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_stormwater_2020_16_4','stat_stormwater_2020_16','Section 12.6',4,'Erosion Control','Sites disturbing more than 50 sq m require erosion control during construction. Field verification occurs at the corresponding inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_stormwater_2020_16_5','stat_stormwater_2020_16','Section 8.2',5,'Grading Permit','A separate grading permit is required where cut or fill exceeds 0.6 m. Documentation must be retained for the life of the structure.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_residential_2026_17','Residential Building Code No. 27-26 (Amended) for Pier District','RBC-26','Harbor City Building Division','2026-04-22','现行有效','Consolidated 2026 revision superseding earlier departmental memoranda. Amendments are published quarterly.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2026_17_1','stat_residential_2026_17','Section 4.6',1,'Foundation and Slab','Slab-on-grade conversions must document existing slab thickness and vapor barrier; a structural observation report is required where the slab predates 1990. Field verification occurs at the corresponding inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2026_17_2','stat_residential_2026_17','Section 10.6',2,'Wall Framing','Converted framing must meet current lateral bracing requirements; existing garage door headers may be retained only with an engineer letter. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2026_17_3','stat_residential_2026_17','Section 7.4',3,'Roof and Attic Access','Habitable conversions require documented attic access and insulation baffles at eave vents. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2026_17_4','stat_residential_2026_17','Section 1.6',4,'Stairs and Landings','Any level change greater than 190 mm requires a compliant step and landing at exterior doors. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2026_17_5','stat_residential_2026_17','Section 11.5',5,'Weather Protection','Exterior wall assemblies must include a water-resistive barrier continuous with the existing structure. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_electrical_2022_18','Electrical Safety Ordinance No. 88-22 (Consolidated): Existing Buildings','ESO-22','Harbor City Electrical Board','2022-12-19','已废止','Sets minimum standards for rental registration. Amendments are published quarterly.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_electrical_2022_18_1','stat_electrical_2022_18','Section 9.5',1,'Branch Circuits','A converted dwelling unit requires dedicated small-appliance branch circuits separate from the main residence panel. Field verification occurs at the corresponding inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_electrical_2022_18_2','stat_electrical_2022_18','Section 12.3',2,'GFCI and AFCI','GFCI protection is required at kitchenette, bathroom and exterior outlets; AFCI protection is required at sleeping areas.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_electrical_2022_18_3','stat_electrical_2022_18','Section 3.3',3,'Sub-panel Feed','Detached structures require a properly sized feeder, grounding electrode and disconnecting means. See the departmental checklist for submittal format.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_electrical_2022_18_4','stat_electrical_2022_18','Section 4.3',4,'Working Clearance','Panels must retain 900 mm clear working depth; storage may not encroach on that clearance.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_electrical_2022_18_5','stat_electrical_2022_18','Section 6.6',5,'Exterior Lighting','An independent entrance requires illumination controlled from inside the unit. Field verification occurs at the corresponding inspection.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_plumbing_2020_19','Plumbing and Drainage Rules No. 88-20 (Supplement) — Infill Sites Part','PDR-20','Harbor City Utilities Department','2020-05-19','已废止','Adopted after the 2020 code cycle; enforced at plan check and field inspection. Local amendments take precedence over the model code.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_plumbing_2020_19_1','stat_plumbing_2020_19','Section 10.5',1,'Sewer Connection','A new dwelling unit connection requires a capacity confirmation letter from the utility before rough plumbing inspection. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_plumbing_2020_19_2','stat_plumbing_2020_19','Section 11.5',2,'Water Metering','Sub-metering is optional for accessory units but the shutoff must be accessible without entering the main residence. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_plumbing_2020_19_3','stat_plumbing_2020_19','Section 8.9',3,'Fixture Seals and Venting','Every fixture requires an individual water seal and a vent connected to the existing stack or a new roof vent.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_plumbing_2020_19_4','stat_plumbing_2020_19','Section 5.4',4,'Backflow Prevention','Irrigation and hose bibs serving the rear yard require backflow devices. See the departmental checklist for submittal format.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_plumbing_2020_19_5','stat_plumbing_2020_19','Section 12.5',5,'Hot Water','Storage water heaters in habitable conversions require seismic strapping and a drain pan piped to daylight. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_zoning_2019_20','Zoning and Setback Bulletin No. 38-19 (Interim)','ZSB-19','Harbor City Planning Department','2019-10-14','现行有效','Sets minimum standards for accessory structures. Does not apply to structures under 10 sq m.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2019_20_1','stat_zoning_2019_20','Section 3.1',1,'Rear Yard Coverage','Accessory structures may occupy up to 50 percent of the required rear yard; existing nonconforming coverage may be retained if not expanded. Field verification occurs at the corresponding inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2019_20_2','stat_zoning_2019_20','Section 4.4',2,'Side Setback','A detached accessory structure must maintain a 1.2 m side setback unless the existing wall is fire-rated. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2019_20_3','stat_zoning_2019_20','Section 3.2',3,'Height Limit','Single-storey accessory structures are limited to 5 m measured to the roof midpoint. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2019_20_4','stat_zoning_2019_20','Section 2.9',4,'Lot Coverage','Total impervious coverage may not exceed the district maximum after conversion. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2019_20_5','stat_zoning_2019_20','Section 11.2',5,'Tree Protection','Work within the dripline of a protected tree requires an arborist report before permit issuance. Field verification occurs at the corresponding inspection.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_neighborhood_2025_21','Neighborhood Notice Procedure No. 26-25: Additions','NNP-25','Harbor City Clerk Office','2025-02-11','现行有效','Applies to detached accessory structures in R-2 districts. Amendments are published quarterly.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2025_21_1','stat_neighborhood_2025_21','Section 9.6',1,'Notice Radius','Applications for detached accessory dwelling conversions require mailed notice to owners within 100 m. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2025_21_2','stat_neighborhood_2025_21','Section 9.2',2,'Objection Window','Written objections must be filed within 14 days of notice; late objections are recorded but do not stay the permit.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2025_21_3','stat_neighborhood_2025_21','Section 7.6',3,'Hearing Threshold','A hearing is scheduled only where objections raise a code-based issue rather than general opposition. Field verification occurs at the corresponding inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2025_21_4','stat_neighborhood_2025_21','Section 7.7',4,'Response Record','The applicant response to each objection is entered into the permit case record. Field verification occurs at the corresponding inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2025_21_5','stat_neighborhood_2025_21','Section 4.4',5,'Appeal Rights','A permit decision may be appealed within 10 days by any party who filed a timely objection. Field verification occurs at the corresponding inspection.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_fire_2026_22','Fire Prevention Standard No. 6-26 (Amended) for Marsh End','FPS-26','Harbor City Fire Marshal','2026-06-15','已修订','Interpretation guidance issued by Harbor City Fire Marshal. Amendments are published quarterly.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2026_22_1','stat_fire_2026_22','Section 5.5',1,'Separation','A dwelling conversion sharing a wall with a garage requires a one-hour rated separation with self-closing doors. See the departmental checklist for submittal format.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2026_22_2','stat_fire_2026_22','Section 5.1',2,'Address Marking','Rear units must display an address marker visible from the access path.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2026_22_3','stat_fire_2026_22','Section 6.4',3,'Extinguisher','A portable extinguisher is recommended but not required for single accessory units.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2026_22_4','stat_fire_2026_22','Section 3.6',4,'Access Path','An unobstructed 900 mm path must connect the street to the unit entrance. Field verification occurs at the corresponding inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2026_22_5','stat_fire_2026_22','Section 11.3',5,'Alarm Interconnection','Where more than one alarm is installed, alarms must be interconnected so that activation of one sounds all. Alternative means may be approved by the building official.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_rental_2025_23','Rental Housing Registration No. 24-25 (Reissued) — Rental Housing Part','RHR-25','Harbor City Housing Office','2025-08-19','已废止','Consolidated 2025 revision superseding earlier departmental memoranda.');
