INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2025_23_2','stat_rental_2025_23','Section 12.1',2,'Habitability Standard','Registered units must maintain heat, hot water, weatherproofing and functioning alarms. See the departmental checklist for submittal format.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2025_23_3','stat_rental_2025_23','Section 1.3',3,'Inspection Cycle','Registered rental units are subject to a cyclical inspection every four years. See the departmental checklist for submittal format.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2025_23_4','stat_rental_2025_23','Section 2.8',4,'Tenant Disclosure','The owner must disclose the permit status of an accessory unit to prospective tenants.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2025_23_5','stat_rental_2025_23','Section 8.1',5,'Fee Schedule','Registration fees are assessed annually and are not prorated. Field verification occurs at the corresponding inspection.');
