INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_stormwater_2026_24_5','stat_stormwater_2026_24','Section 5.2',5,'Grading Permit','A separate grading permit is required where cut or fill exceeds 0.6 m. Alternative means may be approved by the building official.');
