INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2020_29_1','stat_neighborhood_2020_29','Section 4.4',1,'Notice Radius','Applications for detached accessory dwelling conversions require mailed notice to owners within 100 m.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2020_29_2','stat_neighborhood_2020_29','Section 6.4',2,'Objection Window','Written objections must be filed within 14 days of notice; late objections are recorded but do not stay the permit. Field verification occurs at the corresponding inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2020_29_3','stat_neighborhood_2020_29','Section 12.6',3,'Hearing Threshold','A hearing is scheduled only where objections raise a code-based issue rather than general opposition. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2020_29_4','stat_neighborhood_2020_29','Section 2.9',4,'Response Record','The applicant response to each objection is entered into the permit case record. See the departmental checklist for submittal format.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2020_29_5','stat_neighborhood_2020_29','Section 9.9',5,'Appeal Rights','A permit decision may be appealed within 10 days by any party who filed a timely objection. Alternative means may be approved by the building official.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_fire_2020_30','Fire Prevention Standard No. 8-20 (Interim) for Outer Wards','FPS-20','Harbor City Fire Marshal','2020-07-10','现行有效','Sets minimum standards for additions. Applies only to permits filed after the effective date.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2020_30_1','stat_fire_2020_30','Section 12.5',1,'Separation','A dwelling conversion sharing a wall with a garage requires a one-hour rated separation with self-closing doors. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2020_30_2','stat_fire_2020_30','Section 1.1',2,'Address Marking','Rear units must display an address marker visible from the access path. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2020_30_3','stat_fire_2020_30','Section 7.9',3,'Extinguisher','A portable extinguisher is recommended but not required for single accessory units. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2020_30_4','stat_fire_2020_30','Section 9.4',4,'Access Path','An unobstructed 900 mm path must connect the street to the unit entrance. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2020_30_5','stat_fire_2020_30','Section 1.7',5,'Alarm Interconnection','Where more than one alarm is installed, alarms must be interconnected so that activation of one sounds all. Field verification occurs at the corresponding inspection.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_rental_2024_31','Rental Housing Registration No. 42-24 (Interim) for Outer Wards','RHR-24','Harbor City Housing Office','2024-09-15','现行有效','Interpretation guidance issued by Harbor City Housing Office. Does not apply to structures under 10 sq m.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2024_31_1','stat_rental_2024_31','Section 5.4',1,'Registration Duty','A newly created rental unit must be registered within 30 days of first occupancy. See the departmental checklist for submittal format.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2024_31_2','stat_rental_2024_31','Section 6.4',2,'Habitability Standard','Registered units must maintain heat, hot water, weatherproofing and functioning alarms. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2024_31_3','stat_rental_2024_31','Section 4.5',3,'Inspection Cycle','Registered rental units are subject to a cyclical inspection every four years. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2024_31_4','stat_rental_2024_31','Section 12.7',4,'Tenant Disclosure','The owner must disclose the permit status of an accessory unit to prospective tenants. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2024_31_5','stat_rental_2024_31','Section 2.5',5,'Fee Schedule','Registration fees are assessed annually and are not prorated.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_stormwater_2019_32','Stormwater and Grading No. 35-19 (Reissued)','SG-19','Harbor City Public Works','2019-07-05','现行有效','Interpretation guidance issued by Harbor City Public Works. Local amendments take precedence over the model code.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_stormwater_2019_32_1','stat_stormwater_2019_32','Section 5.4',1,'Drainage Away','Finished grade must fall away from the converted structure for the first 1.5 m. See the departmental checklist for submittal format.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_stormwater_2019_32_2','stat_stormwater_2019_32','Section 11.3',2,'Downspout Discharge','Downspouts may not discharge onto an adjacent property. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_stormwater_2019_32_3','stat_stormwater_2019_32','Section 10.4',3,'Permeable Area','Replacement of a driveway apron requires maintaining the district permeable minimum. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_stormwater_2019_32_4','stat_stormwater_2019_32','Section 2.4',4,'Erosion Control','Sites disturbing more than 50 sq m require erosion control during construction. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_stormwater_2019_32_5','stat_stormwater_2019_32','Section 6.4',5,'Grading Permit','A separate grading permit is required where cut or fill exceeds 0.6 m. See the departmental checklist for submittal format.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_residential_2021_33','Residential Building Code No. 88-21 (Supplement): Additions','RBC-21','Harbor City Building Division','2021-05-03','已废止','Sets minimum standards for additions. Amendments are published quarterly.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2021_33_1','stat_residential_2021_33','Section 4.7',1,'Foundation and Slab','Slab-on-grade conversions must document existing slab thickness and vapor barrier; a structural observation report is required where the slab predates 1990. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2021_33_2','stat_residential_2021_33','Section 1.2',2,'Wall Framing','Converted framing must meet current lateral bracing requirements; existing garage door headers may be retained only with an engineer letter. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2021_33_3','stat_residential_2021_33','Section 8.3',3,'Roof and Attic Access','Habitable conversions require documented attic access and insulation baffles at eave vents. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2021_33_4','stat_residential_2021_33','Section 9.3',4,'Stairs and Landings','Any level change greater than 190 mm requires a compliant step and landing at exterior doors. See the departmental checklist for submittal format.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2021_33_5','stat_residential_2021_33','Section 1.5',5,'Weather Protection','Exterior wall assemblies must include a water-resistive barrier continuous with the existing structure. See the departmental checklist for submittal format.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_electrical_2019_34','Electrical Safety Ordinance No. 58-19 (Consolidated) — Historic District Part','ESO-19','Harbor City Electrical Board','2019-08-04','现行有效','Interpretation guidance issued by Harbor City Electrical Board.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_electrical_2019_34_1','stat_electrical_2019_34','Section 12.8',1,'Branch Circuits','A converted dwelling unit requires dedicated small-appliance branch circuits separate from the main residence panel. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_electrical_2019_34_2','stat_electrical_2019_34','Section 7.2',2,'GFCI and AFCI','GFCI protection is required at kitchenette, bathroom and exterior outlets; AFCI protection is required at sleeping areas. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_electrical_2019_34_3','stat_electrical_2019_34','Section 7.6',3,'Sub-panel Feed','Detached structures require a properly sized feeder, grounding electrode and disconnecting means. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_electrical_2019_34_4','stat_electrical_2019_34','Section 2.3',4,'Working Clearance','Panels must retain 900 mm clear working depth; storage may not encroach on that clearance. See the departmental checklist for submittal format.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_electrical_2019_34_5','stat_electrical_2019_34','Section 11.3',5,'Exterior Lighting','An independent entrance requires illumination controlled from inside the unit. See the departmental checklist for submittal format.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_plumbing_2020_35','Plumbing and Drainage Rules No. 73-20 (Consolidated) for Oakview','PDR-20','Harbor City Utilities Department','2020-02-25','现行有效','Interpretation guidance issued by Harbor City Utilities Department. Amendments are published quarterly.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_plumbing_2020_35_1','stat_plumbing_2020_35','Section 1.9',1,'Sewer Connection','A new dwelling unit connection requires a capacity confirmation letter from the utility before rough plumbing inspection. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_plumbing_2020_35_2','stat_plumbing_2020_35','Section 8.4',2,'Water Metering','Sub-metering is optional for accessory units but the shutoff must be accessible without entering the main residence. See the departmental checklist for submittal format.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_plumbing_2020_35_3','stat_plumbing_2020_35','Section 4.2',3,'Fixture Seals and Venting','Every fixture requires an individual water seal and a vent connected to the existing stack or a new roof vent. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_plumbing_2020_35_4','stat_plumbing_2020_35','Section 6.5',4,'Backflow Prevention','Irrigation and hose bibs serving the rear yard require backflow devices. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_plumbing_2020_35_5','stat_plumbing_2020_35','Section 8.1',5,'Hot Water','Storage water heaters in habitable conversions require seismic strapping and a drain pan piped to daylight. Documentation must be retained for the life of the structure.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_zoning_2025_36','Zoning and Setback Bulletin No. 6-25 (Supplement) — Residential Part','ZSB-25','Harbor City Planning Department','2025-03-09','现行有效','Interpretation guidance issued by Harbor City Planning Department.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2025_36_1','stat_zoning_2025_36','Section 11.5',1,'Rear Yard Coverage','Accessory structures may occupy up to 50 percent of the required rear yard; existing nonconforming coverage may be retained if not expanded. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2025_36_2','stat_zoning_2025_36','Section 1.9',2,'Side Setback','A detached accessory structure must maintain a 1.2 m side setback unless the existing wall is fire-rated. See the departmental checklist for submittal format.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2025_36_3','stat_zoning_2025_36','Section 3.5',3,'Height Limit','Single-storey accessory structures are limited to 5 m measured to the roof midpoint. See the departmental checklist for submittal format.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2025_36_4','stat_zoning_2025_36','Section 4.4',4,'Lot Coverage','Total impervious coverage may not exceed the district maximum after conversion. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_zoning_2025_36_5','stat_zoning_2025_36','Section 2.4',5,'Tree Protection','Work within the dripline of a protected tree requires an arborist report before permit issuance. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_neighborhood_2022_37','Neighborhood Notice Procedure No. 36-22 (Supplement)','NNP-22','Harbor City Clerk Office','2022-10-09','现行有效','Sets minimum standards for additions. Does not apply to structures under 10 sq m.');
