INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2022_37_3','stat_neighborhood_2022_37','Section 10.6',3,'Hearing Threshold','A hearing is scheduled only where objections raise a code-based issue rather than general opposition. See the departmental checklist for submittal format.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2022_37_4','stat_neighborhood_2022_37','Section 1.6',4,'Response Record','The applicant response to each objection is entered into the permit case record. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_neighborhood_2022_37_5','stat_neighborhood_2022_37','Section 9.4',5,'Appeal Rights','A permit decision may be appealed within 10 days by any party who filed a timely objection. See the departmental checklist for submittal format.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_fire_2022_38','Fire Prevention Standard No. 44-22 (Reissued): Existing Buildings','FPS-22','Harbor City Fire Marshal','2022-05-19','现行有效','Applies to detached accessory structures in MU-1 districts. Does not apply to structures under 10 sq m.');
