INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2022_38_2','stat_fire_2022_38','Section 11.6',2,'Address Marking','Rear units must display an address marker visible from the access path. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2022_38_3','stat_fire_2022_38','Section 1.6',3,'Extinguisher','A portable extinguisher is recommended but not required for single accessory units. Field verification occurs at the corresponding inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2022_38_4','stat_fire_2022_38','Section 7.4',4,'Access Path','An unobstructed 900 mm path must connect the street to the unit entrance. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_fire_2022_38_5','stat_fire_2022_38','Section 9.9',5,'Alarm Interconnection','Where more than one alarm is installed, alarms must be interconnected so that activation of one sounds all. Documentation must be retained for the life of the structure.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_rental_2021_39','Rental Housing Registration No. 47-21 (Reissued) — Infill Sites Part','RHR-21','Harbor City Housing Office','2021-03-13','现行有效','Sets minimum standards for rental registration.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2021_39_1','stat_rental_2021_39','Section 7.1',1,'Registration Duty','A newly created rental unit must be registered within 30 days of first occupancy. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2021_39_2','stat_rental_2021_39','Section 5.6',2,'Habitability Standard','Registered units must maintain heat, hot water, weatherproofing and functioning alarms. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2021_39_3','stat_rental_2021_39','Section 4.5',3,'Inspection Cycle','Registered rental units are subject to a cyclical inspection every four years. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2021_39_4','stat_rental_2021_39','Section 10.1',4,'Tenant Disclosure','The owner must disclose the permit status of an accessory unit to prospective tenants. Field verification occurs at the corresponding inspection.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_rental_2021_39_5','stat_rental_2021_39','Section 12.8',5,'Fee Schedule','Registration fees are assessed annually and are not prorated. Noncompliance is corrected by written notice before final approval.');
