INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_stormwater_2020_40_3','stat_stormwater_2020_40','Section 1.2',3,'Permeable Area','Replacement of a driveway apron requires maintaining the district permeable minimum. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_stormwater_2020_40_4','stat_stormwater_2020_40','Section 1.3',4,'Erosion Control','Sites disturbing more than 50 sq m require erosion control during construction. Alternative means may be approved by the building official.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_stormwater_2020_40_5','stat_stormwater_2020_40','Section 9.6',5,'Grading Permit','A separate grading permit is required where cut or fill exceeds 0.6 m. Noncompliance is corrected by written notice before final approval.');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_residential_2025_41','Residential Building Code No. 76-25 (Reissued): Detached Units','RBC-25','Harbor City Building Division','2025-06-17','现行有效','Applies to detached accessory structures in MU-1 districts. Amendments are published quarterly.');
