INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2025_41_2','stat_residential_2025_41','Section 4.5',2,'Wall Framing','Converted framing must meet current lateral bracing requirements; existing garage door headers may be retained only with an engineer letter. Documentation must be retained for the life of the structure.');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_residential_2025_41_3','stat_residential_2025_41','Section 2.8',3,'Roof and Attic Access','Habitable conversions require documented attic access and insulation baffles at eave vents. Field verification occurs at the corresponding inspection.');
