INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_electrical_2025_42','Electrical Safety Ordinance No. 17-25 for Oakview','ESO-25','Harbor City Electrical Board','2025-08-27','已废止','Sets minimum standards for conversions. Local amendments take precedence over the model code.');
